const res = pm.response;
const body = res.json();
pm.test("4xx (client error) not 5xx (server error/crash)",()=>{
    pm.expect(res.code).to.be.within(400,499)
    });
pm.test("error code and message",()=>{
    pm.expect(body.error).to.exist;
    pm.expect(body.error.code).to.be.a("string");
    pm.expect(body.error.message).to.be.a("string").and.not.empty;
    });
pm.test("traceable operation with id",()=>{
    pm.expect(res.headers.get("Request-id")).to.match(/^req_/);
    });
pm.test("no secret key communicated",()=>{
    pm.expect(res.text()).to.not.include(pm.environment.get("secret_key"));
});
